package com.example.inventory;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Predicate;

/** A simple inventory. */
public class Inventory {
    public record Item(String name, int count) {}

    public sealed interface Event permits Added, Removed {}
    public record Added(Item item) implements Event {}
    public record Removed(String name) implements Event {}

    private static final String HELP = """
        Inventory help
        """;

    private final List<Item> items = new ArrayList<>();

    public void add(Item item) {
        if (item == null) {
            throw new IllegalArgumentException("item");
        }
        items.add(item);
    }

    public List<Item> filter(Predicate<Item> test) {
        var result = new ArrayList<Item>();
        for (Item item : items) {
            if (test.test(item)) {
                result.add(item);
            }
        }
        return result;
    }

    public static String describe(Event event) {
        return switch (event) {
            case Added a when a.item().count() > 100 -> "bulk " + a.item().name();
            case Added a -> "added " + a.item().name();
            case Removed r -> "removed " + r.name();
        };
    }

    public long total() {
        // Sum of all counts.
        return items.stream().mapToLong(Item::count).sum();
    }
}

